#include <cstdlib>
#include <fstream>
#include <iostream>
#include <iterator>
#include <sstream>
#include <string>
#include <vector>
using namespace std;

// 独立实现期望值：小写贡献序号，大写贡献 -ASCII
static long long expected(const string& t) {
    long long ans = 0;
    for (size_t i = 0; i < t.size(); ++i) {
        char c = t[i];
        if (c >= 'a' && c <= 'z') ans += c - 'a' + 1;
        else if (c >= 'A' && c <= 'Z') ans -= (unsigned char)c;
    }
    return ans;
}

static bool check(const string& exe, const string& t, int id) {
    const string inFile = "a2403p1_input.txt", outFile = "a2403p1_output.txt";
    {
        ofstream out(inFile);
        out << t.size() << '\n' << t << '\n';
    }
    string cmd = "\"" + exe + "\" < " + inFile + " > " + outFile + " 2>/dev/null";
    int code = system(cmd.c_str());
    ifstream in(outFile);
    string output((istreambuf_iterator<char>(in)), istreambuf_iterator<char>());
    istringstream parser(output);
    long long actual = 0;
    string extra;
    const long long want = expected(t);
    bool ok = code == 0 && (parser >> actual) && !(parser >> extra) && actual == want;
    if (!ok) {
        cout << "[FAIL] case " << id << ": n=" << t.size() << ", expected=" << want
             << ", actual=" << output.substr(0, 120) << ", process status=" << code << '\n';
    }
    return ok;
}

int main(int argc, char* argv[]) {
    if (argc < 2) return 2;
    if (expected("aAc") != -61) { cout << "[FAIL] self-check: expected(aAc) != -61\n"; return 2; }
    vector<string> tests = {
        "aAc", "a", "Z", "abcdefghijklmnopqrstuvwxyz", "ABC",
        "AaBbCcDdEe", "zZ", "gEsP", "QQQQQQQQQQ", "mmmmmmmmmm"
    };
    srand(202403u);
    for (int trial = 0; trial < 5; ++trial) {
        int n = (trial == 4) ? 100000 : 1 + trial * 251;
        string s;
        for (int i = 0; i < n; ++i) {
            int c = rand() % 52;
            s += (char)(c < 26 ? 'a' + c : 'A' + (c - 26));
        }
        tests.push_back(s);
    }
    int pass = 0;
    const int total = (int)tests.size();
    for (int i = 0; i < total; ++i) pass += check(argv[1], tests[i], i) ? 1 : 0;
    cout << "Results: " << pass << "/" << total << " passed" << endl;
    return pass == total ? 0 : 1;
}

